        lessons: [
            { id: "a1_m11_l1", title: "Technical Documentation", content: "<p>Leitura: <b>Read the API documentation</b> <button class='speak-btn' data-text='Read the API documentation.'>🔊</button>.</p>", quiz: { question: "O que significa 'read the docs'?", options: ["escrever código", "ler a documentação técnica", "deletar arquivos", "chamar suporte"], correctIndex: 1, explanation: "Read the docs é a instrução para ler a documentação." } },
            { id: "a1_m11_l2", title: "README Files", content: "<p>README: <b>Create a README file for the project</b> <button class='speak-btn' data-text='Create a README file for the project.'>🔊</button>.</p>", quiz: { question: "Qual é a função do README?", options: ["conter código de execução", "apresentar instruções iniciais do repositório", "salvar banco de dados", "fazer backup de senhas"], correctIndex: 1, explanation: "README contém instruções e metadados iniciais do projeto." } },
            { id: "a1_m11_l3", title: "Headers in Markdown", content: "<p>Títulos: <b>Use hash symbols for headers in markdown</b> (Use hashtags # para títulos no markdown).</p>", quiz: { question: "Como criar um título principal no Markdown?", options: ["usando #", "usando *", "usando -", "usando @"], correctIndex: 0, explanation: "O caractere '#' cria cabeçalhos e títulos no Markdown." } },
            { id: "a1_m11_l4", title: "Code Blocks", content: "<p>Código: <b>Use triple backticks for code blocks</b> <button class='speak-btn' data-text='code blocks'>🔊</button> (Use crases triplas para blocos de código).</p>", quiz: { question: "Qual símbolo delimita blocos de código no Markdown?", options: ["crases triplas (```)", "aspas duplas", "parênteses", "hífenes"], correctIndex: 0, explanation: "Crases triplas geram blocos de código formatados no Markdown." } },
            { id: "a1_m11_l5", title: "Links in Markdown", content: "<p>Links: <b>Format links using brackets and parentheses</b> (Formate links usando colchetes e parênteses).</p>", quiz: { question: "Qual é a ordem correta para criar links em markdown?", options: ["(texto)[URL]", "[texto](URL)", "{texto}[URL]", "@texto(URL)"], correctIndex: 1, explanation: "[link text](URL) é a sintaxe do Markdown." } },
            { id: "a1_m11_l6", title: "Bold and Italic text", content: "<p>Estilos: <b>Use double asterisks for bold</b> <button class='speak-btn' data-text='bold'>🔊</button> e <b>single asterisk for italic</b> <button class='speak-btn' data-text='italic'>🔊</button>.</p>", quiz: { question: "Como deixar um texto em negrito no Markdown?", options: ["*texto*", "**texto**", "#texto", "_texto_"], correctIndex: 1, explanation: "Asteriscos duplos (**) deixam o texto em negrito." } },
            { id: "a1_m11_l7", title: "Lists formatting", content: "<p>Listas: <b>Use hyphens for bullet points</b> <button class='speak-btn' data-text='bullet points'>🔊</button> (Use hífens para listas com marcadores).</p>", quiz: { question: "Como fazer marcadores de tópicos?", options: ["hífens (-)", "arroba (@)", "cifrão ($)", "porcentagem (%)"], correctIndex: 0, explanation: "Hífens ou asteriscos geram tópicos desordenados." } },
            { id: "a1_m11_l8", title: "Tables in Markdown", content: "<p>Tabelas: <b>Create tables using pipe symbols</b> <button class='speak-btn' data-text='tables'>🔊</button> (Crie tabelas usando barras verticais |).</p>", quiz: { question: "Qual símbolo separa colunas de tabelas no markdown?", options: ["hífen", "barra vertical (|)", "vírgula", "ponto e vírgula"], correctIndex: 1, explanation: "A barra vertical (|) é a divisória de colunas no markdown." } },
            { id: "a1_m11_l9", title: "Inline Code formatting", content: "<p>Inline: <b>Use single backticks for inline code</b> (Use crase simples para código inline no meio do texto).</p>", quiz: { question: "Como destacar uma única palavra como código?", options: ["`palavra`", "```palavra```", "**palavra**", "#palavra"], correctIndex: 0, explanation: "Crases simples criam código inline." } },
            { id: "a1_m11_l10", title: "Documentation Done", content: "<p>Conclusão: <b>The README file is complete</b> <button class='speak-btn' data-text='The README file is complete.'>🔊</button>.</p>", quiz: { question: "Como dizemos 'completo'?", options: ["crashed", "complete", "failed", "offline"], correctIndex: 1, explanation: "Complete significa completo ou concluído." } }
        ]
